<script lang="ts">
 import { dialogFocus } from './lib/dialog';
 import { budget, changeCategory, changeGroup, createCategory, formatMoney, type BudgetView } from './lib/api';
 import BudgetRow from './BudgetRow.svelte'; import MonthNav from './MonthNav.svelte';
 let {version, month = $bindable(), currentMonth, refresh}: {version:string; month:number; currentMonth:number; refresh:()=>void} = $props();
 let data = $state<BudgetView|null>(null), error = $state(''), showHidden = $state(false), local = $state(0), name = $state('');
 let target = $state<{kind:'group'|'category'|'newCategory'; id:number|null; title:string}|null>(null); let request = 0;
 $effect(() => { const m = month; void version; void local; if (!m) return; const id = ++request; void budget(m).then(v => {if(id===request) data=v;}).catch(e => error=String(e)); });
 function updated(){local++; refresh();}
 async function save(){if (!target || !name.trim()) return; try { if(target.kind==='group') await changeGroup(target.id,name); else if(target.kind==='newCategory') await createCategory(target.id!,name); else await changeCategory(target.id!,name,null); target=null; updated(); } catch(e){error=String(e);} }
 async function toggle(id:number, hidden:boolean){try{await changeCategory(id,null,!hidden); updated();}catch(e){error=String(e);}}
 const title = (m:number) => new Intl.DateTimeFormat('es-MX',{month:'long',year:'numeric'}).format(new Date(Math.floor(m/100), m%100-1, 1));
</script>
<div class="screen"><header><div><h1>Dale un destino a tu dinero</h1><p>{month ? title(month) : ''}</p></div><MonthNav bind:month {currentMonth}/></header>
{#if error}<p class="error" role="alert">{error}</p>{/if}
{#if data}<div class="metrics"><section><h2>Disponible para asignar</h2><strong class:negative={data.toBudget < 0}>{formatMoney(data.toBudget)}</strong><p>{data.hint}</p></section><section><h2>Ingresos del mes</h2><strong class="income">{formatMoney(data.income)}</strong></section><section><h2>Asignado</h2><strong>{formatMoney(data.assigned)}</strong></section></div>
{#if data.uncategorizedIncome > 0}<p class="banner">Tienes {formatMoney(data.uncategorizedIncome)} en ingresos sin categoría. Dales una categoría de ingreso en Movimientos para poder repartirlos.</p>{/if}
<p>Escribe cuánto asignas a cada categoría, o usa +100 / -50 para sumar o restar.</p><div class="toolbar"><button onclick={() => {name='';target={kind:'group',id:null,title:'Nuevo grupo'};}}>Nuevo grupo</button><label><input type="checkbox" bind:checked={showHidden}/> Mostrar ocultas</label></div>
{#each data.groups as group (group.id)}<section class="group"><header role="group" oncontextmenu={e => {e.preventDefault(); const menu=e.currentTarget.querySelector('details'); if(menu) menu.open=true;}}><h2>{group.name}</h2><div><button aria-label={`Nueva categoría en ${group.name}`} onclick={() => {name='';target={kind:'newCategory',id:group.id,title:`Nueva categoría en ${group.name}`};}}>＋</button><details><summary aria-label={`Acciones del grupo ${group.name}`}>⋯</summary><button onclick={() => {name=group.name;target={kind:'group',id:group.id,title:'Renombrar grupo'};}}>Renombrar grupo</button></details></div></header><div class="table"><table><thead><tr><th>Categoría</th>{#if !group.isIncome}<th>Asignado</th><th>Gastado</th><th>Disponible</th>{:else}<th>Actividad</th>{/if}<th>Acciones</th></tr></thead><tbody>{#each group.categories.filter(c => showHidden || !c.hidden) as row (row.id)}<tr class:hidden={row.hidden} oncontextmenu={e => {e.preventDefault(); const menu=e.currentTarget.querySelector('details'); if(menu) menu.open=true;}}>
{#if group.isIncome}<td>{row.name}</td><td class="income">{formatMoney(row.activity)}</td>{:else}<BudgetRow {row} {month} refresh={updated}/>{/if}
<td><details><summary aria-label={`Acciones de ${row.name}`}>⋯</summary><button onclick={() => {name=row.name;target={kind:'category',id:row.id,title:'Renombrar categoría'};}}>Renombrar</button><button onclick={() => toggle(row.id,row.hidden)}>{row.hidden ? 'Mostrar' : 'Ocultar'}</button></details></td></tr>{/each}</tbody></table></div></section>{/each}{/if}</div>
{#if target}<div class="backdrop"><div class="modal" use:dialogFocus role="dialog" aria-modal="true" aria-labelledby="budget-dialog" tabindex="-1" onkeydown={e => {if(e.key==='Escape') target=null;}}><h2 id="budget-dialog">{target.title}</h2><form onsubmit={e => {e.preventDefault();void save();}}><label>Nombre <input bind:value={name} required/></label><div><button type="button" onclick={() => target=null}>Cancelar</button><button type="submit">Guardar</button></div></form></div></div>{/if}
<style>.screen{display:grid;gap:18px;max-width:1500px;margin:auto}header,.toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}h1,h2,p{margin:0}h2{font-size:1rem}p{color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px}.metrics section,.group{background:var(--card);border:1px solid var(--border);border-radius:18px;padding:20px}.metrics strong{display:block;font-size:1.5rem;margin:10px 0}.income{color:var(--emerald)}.negative,.error{color:var(--coral)}.banner{padding:14px;color:var(--amber);background:color-mix(in srgb,var(--amber) 10%,transparent);border-radius:10px}.table{overflow:auto}table{border-collapse:collapse;width:100%}th,td{padding:10px;border-bottom:1px solid var(--border);text-align:left}th:not(:first-child),td:not(:first-child){text-align:right}tr.hidden{opacity:.5}button,summary{cursor:pointer}button,input{font:inherit}button{padding:7px;border:1px solid var(--border);border-radius:8px;background:var(--canvas);color:inherit}details{position:relative}header details{display:inline-block}details button{display:block;white-space:nowrap}.backdrop{position:fixed;inset:0;background:#0009;display:grid;place-items:center;z-index:10}.modal{background:var(--card);padding:24px;border-radius:16px;min-width:300px}.modal form{display:grid;gap:16px;margin-top:16px}.modal form div{display:flex;justify-content:flex-end;gap:8px}.modal input{font:inherit;max-width:100%}</style>
